        w1, w2 = 1.0, 1.7321

        def coil(xa, xb, y, n=6, amp=0.13):
            a = np.array([xa, y, 0.0]); b = np.array([xb, y, 0.0])
            out = [a]
            for i in range(1, 4 * n):
                out.append(a + (b - a) * i / (4 * n) + np.array([0.0, amp * (1 if i % 2 else -1), 0.0]))
            out.append(b)
            v = VMobject(color=GREY_B, stroke_width=2)
            v.set_points_as_corners(out)
            return v

        def system(y, pos1, pos2, size, walls=(-4.6, 4.6)):
            wl = Line([walls[0], y - 0.45, 0], [walls[0], y + 0.45, 0], color=GREY_A, stroke_width=5)
            wr = Line([walls[1], y - 0.45, 0], [walls[1], y + 0.45, 0], color=GREY_A, stroke_width=5)
            springs = always_redraw(lambda: VGroup(coil(walls[0], pos1(), y), coil(pos1(), pos2(), y),
                                                   coil(pos2(), walls[1], y)))
            m1 = always_redraw(lambda: Square(size, color=BLUE, fill_color=BLUE, fill_opacity=0.85).move_to([pos1(), y, 0]))
            m2 = always_redraw(lambda: Square(size, color=TEAL, fill_color=TEAL, fill_opacity=0.85).move_to([pos2(), y, 0]))
            return VGroup(wl, wr, springs, m1, m2)

        title = Text("Energy buckets", font_size=34, color=YELLOW).to_edge(UP, buff=0.25)
        self.play(FadeIn(title), run_time=0.6)

        # Act 1: the two special motions, side by side in time.
        clock = ValueTracker(0.0)
        amp, eq1, eq2 = 0.7, -1.5, 1.5
        together = system(1.4, lambda: eq1 + amp * np.cos(w1 * clock.get_value()),
                          lambda: eq2 + amp * np.cos(w1 * clock.get_value()), 0.42)
        opposite = system(-1.3, lambda: eq1 + amp * np.cos(w2 * clock.get_value()),
                          lambda: eq2 - amp * np.cos(w2 * clock.get_value()), 0.42)
        lab1 = Text('together: ω₁ = 1.00 rad/s', font_size=26, color=BLUE_B).move_to([0, 2.35, 0])
        lab2 = Text('opposite: ω₂ = 1.73 rad/s', font_size=26, color=TEAL_B).move_to([0, -0.35, 0])
        act1 = Text("two special motions: each keeps its own steady rhythm", font_size=24,
                    color=GREY_A).to_edge(DOWN, buff=0.15)
        self.play(FadeIn(together), FadeIn(opposite), FadeIn(lab1), FadeIn(lab2), FadeIn(act1), run_time=0.8)
        self.play(clock.animate.set_value(6.0), run_time=5.0, rate_func=linear)
        for mob in VGroup(together, opposite).get_family():
            mob.clear_updaters()
        self.play(FadeOut(VGroup(together, opposite, lab1, lab2, act1)), run_time=0.6)

        # Act 2: push only the left mass; watch the energy buckets.
        t = ValueTracker(0.0)

        def at(series):
            return float(np.interp(t.get_value(), ts, series))

        main = system(1.5, lambda: -1.5 + 0.9 * at(x1s), lambda: 1.5 + 0.9 * at(x2s), 0.55)
        base_y, full_h = -2.9, 3.0

        def bucket(x, series, color, label):
            frame = Rectangle(width=1.3, height=full_h, color=GREY_B, stroke_width=2).move_to(
                [x, base_y + full_h / 2, 0])
            fill = always_redraw(lambda: Rectangle(
                width=1.26, height=max(0.01, full_h * min(1.0, at(series))), fill_color=color,
                fill_opacity=0.85, stroke_width=0).align_to(frame, DOWN).set_x(x))
            text = Text(label, font_size=22, color=color).next_to(frame, UP, buff=0.12)
            return VGroup(frame, fill, text)

        b1 = bucket(-1.5, e1s, BLUE, "left mass")
        b2 = bucket(1.5, e2s, TEAL, "right mass")
        header = Text("energy held by each mass", font_size=24, color=GREY_A).move_to([0, 0.75, 0])
        act2 = Text("push only the left mass", font_size=24, color=GREY_A).to_edge(DOWN, buff=0.15)
        self.play(FadeIn(main), FadeIn(b1), FadeIn(b2), FadeIn(header), FadeIn(act2), run_time=0.8)
        self.play(t.animate.set_value(4.5432), run_time=4.54, rate_func=linear)
        note = Text('t = 4.5 s: the right mass holds 93% of the moving energy', font_size=24, color=YELLOW_A).to_edge(DOWN, buff=0.15)
        self.play(Indicate(b2[0], color=YELLOW), FadeOut(act2), FadeIn(note), run_time=0.9)
        self.wait(0.8)
        self.play(t.animate.set_value(9.4413), run_time=4.9, rate_func=linear)
        back = Text("...and it pours back again", font_size=24, color=YELLOW_A).to_edge(DOWN, buff=0.15)
        self.play(FadeOut(note), FadeIn(back), run_time=0.6)
        self.wait(1.0)

        # AetherLab explanation layer: clear the stage, then explain what it showed.
        for _m in self.mobjects:
            _m.clear_updaters()
        if self.mobjects:
            self.play(FadeOut(*self.mobjects), run_time=0.8)
        _head = Text('What the animation shows', font_size=34, weight=BOLD, color=YELLOW)
        _eq = Text("m·x₁'' = -2k·x₁ + k·x₂, m·x₂'' = k·x₁ - 2k·x₂", font_size=28, color=WHITE)
        _facts = VGroup(Text('Moving together: ω₁ = √(k/m) = 1.00 rad/s', font_size=25, color=GREY_A), Text('Moving opposite: ω₂ = √(3k/m) = 1.73 rad/s', font_size=25, color=GREY_A), Text('Push one mass: after 4.5 s the other holds 93% of the energy', font_size=25, color=GREY_A)).arrange(DOWN, aligned_edge=LEFT, buff=0.3)
        _key = Text('Pushing one mass starts both special motions at once. They drift in\nand out of step, and the energy sloshes between the masses.', font_size=27, color=TEAL_A)
        _key_box = SurroundingRectangle(_key, color=TEAL, buff=0.22, corner_radius=0.12)
        _card = VGroup(_head, _eq, _facts, VGroup(_key, _key_box)).arrange(DOWN, buff=0.42)
        if _card.width > 12.4:
            _card.scale_to_fit_width(12.4)
        if _card.height > 7.0:
            _card.scale_to_fit_height(7.0)
        self.play(FadeIn(_head, shift=0.2 * DOWN), FadeIn(_eq), run_time=1.2)
        self.play(LaggedStart(*[FadeIn(_f, shift=0.2 * RIGHT) for _f in _facts], lag_ratio=0.85), run_time=4.2)
        self.play(FadeIn(_key), Create(_key_box), run_time=1.2)
        self.wait(1.8)
